    Assert.assertFalse("Integer.MAX_VALUE not_in [Integer.MAX_VALUE] => false", intSetEvaluator.eval(TestHelpers.Row.of(Integer.MAX_VALUE, 7.0, null)));
    Assert.assertTrue("6 not_in [Integer.MAX_VALUE]  => true", intSetEvaluator.eval(TestHelpers.Row.of(6, 6.8, null)));
    Evaluator integerEvaluator = new Evaluator(STRUCT, notIn("y", 7, 8, 9.1));
    Assert.assertFalse("7.0 not in [7, 8, 9] => false", integerEvaluator.eval(TestHelpers.Row.of(0, 7.0, null)));
    Assert.assertFalse("9.1 not in [7, 8, 9.1] => false", integerEvaluator.eval(TestHelpers.Row.of(7, 9.1, null)));
    Assert.assertTrue("6.8 not in [7, 8, 9.1]  => true", integerEvaluator.eval(TestHelpers.Row.of(6, 6.8, null)));
    Evaluator structEvaluator = new Evaluator(STRUCT, notIn("s1.s2.s3.s4.i", 7, 8, 9));
    Assert.assertFalse("7 not in [7, 8, 9] => false", structEvaluator.eval(TestHelpers.Row.of(7, 8, null, TestHelpers.Row.of(TestHelpers.Row.of(TestHelpers.Row.of(TestHelpers.Row.of(7)))))));
    Assert.assertTrue("6 not in [7, 8, 9]  => true", structEvaluator.eval(TestHelpers.Row.of(6, 8, null, TestHelpers.Row.of(TestHelpers.Row.of(TestHelpers.Row.of(TestHelpers.Row.of(6)))))));
    StructType charSeqStruct = StructType.of(required(34, "s", Types.StringType.get()));
    Evaluator charSeqEvaluator = new Evaluator(charSeqStruct, notIn("s", "abc", "abd", "abc"));
    Assert.assertFalse("utf8(abc) not in [string(abc), string(abd)] => false", charSeqEvaluator.eval(TestHelpers.Row.of(new Utf8("abc"))));
    Assert.assertTrue("utf8(abcd) not in [string(abc), string(abd)] => true", charSeqEvaluator.eval(TestHelpers.Row.of(new Utf8("abcd"))));
}

@Test
public void testNotInExceptions() {
    AssertHelpers.assertThrows("Throw exception if value is null", NullPointerException.class, "Cannot create expression literal from null", () -> notIn("x", (Literal) null));
    AssertHelpers.assertThrows("Throw exception if value is null", NullPointerException.class, "Values cannot be null for NOT_IN predicate", () -> notIn("x", (Collection<?>) null));
    AssertHelpers.assertThrows("Throw exception if calling literal() for IN predicate", IllegalArgumentException.class, "NOT_IN predicate cannot return a literal", () -> notIn("x", 5, 6).literal());
    AssertHelpers.assertThrows("Throw exception if any value in the input is null", NullPointerException.class, "Cannot create expression literal from null", () -> notIn("x", 1, 2, null));
    AssertHelpers.assertThrows("Throw exception if binding fails for any element in the set", ValidationException.class, "Invalid value for conversion to type int", () -> new Evaluator(STRUCT, notIn("x", 7, 8, 9.1)));
    AssertHelpers.assertThrows("Throw exception if no input value", IllegalArgumentException.class, "Cannot create NOT_IN predicate without a value", () -> predicate(Expression.Operation.NOT_IN, "x"));
    AssertHelpers.assertThrows("Implicit conversion NOT_IN to NOT_EQ and throw exception if binding fails", ValidationException.class, "Invalid value for conversion to type int", () -> new Evaluator(STRUCT, predicate(Expression.Operation.NOT_IN, "x", 5.1)));
}

