@Test
public void testDateToHumanString() {
    Types.DateType type = Types.DateType.get();
    Literal<Integer> date = Literal.of("2017-12-01").to(type);
    Transform<Integer, Integer> year = Transforms.year(type);
    Assert.assertEquals("Should produce the correct Human string", "2017", year.toHumanString(year.apply(date.value())));
    Transform<Integer, Integer> month = Transforms.month(type);
    Assert.assertEquals("Should produce the correct Human string", "2017-12", month.toHumanString(month.apply(date.value())));
    Transform<Integer, Integer> day = Transforms.day(type);
    Assert.assertEquals("Should produce the correct Human string", "2017-12-01", day.toHumanString(day.apply(date.value())));
}

