public void testMappingFindById() {
    Schema schema = new Schema(required(1, "id", Types.LongType.get()), required(2, "data", Types.StringType.get()), required(3, "map", Types.MapType.ofRequired(4, 5, Types.DoubleType.get(), Types.StructType.of(required(6, "x", Types.DoubleType.get()), required(7, "y", Types.DoubleType.get())))), required(8, "list", Types.ListType.ofRequired(9, Types.StringType.get())), required(10, "location", Types.StructType.of(required(11, "latitude", Types.FloatType.get()), required(12, "longitude", Types.FloatType.get()))));
    NameMapping mapping = MappingUtil.create(schema);
    Assert.assertNull("Should not return a field mapping for a missing ID", mapping.find(100));
    Assert.assertEquals(MappedField.of(2, "data"), mapping.find(2));
    Assert.assertEquals(MappedField.of(6, "x"), mapping.find(6));
    Assert.assertEquals(MappedField.of(9, "element"), mapping.find(9));
    Assert.assertEquals(MappedField.of(11, "latitude"), mapping.find(11));
    Assert.assertEquals(MappedField.of(10, "location", MappedFields.of(MappedField.of(11, "latitude"), MappedField.of(12, "longitude"))), mapping.find(10));
}

