@Test
public void testCreateTransactionConflict() throws IOException {
    File tableDir = temp.newFolder();
    Assert.assertTrue(tableDir.delete());
    Transaction txn = TestTables.beginCreate(tableDir, "test_conflict", SCHEMA, SPEC);
    // append in the transaction to ensure a manifest file is created
    txn.newAppend().appendFile(FILE_A).commit();
    Assert.assertNull("Starting a create transaction should not commit metadata", TestTables.readMetadata("test_conflict"));
    Assert.assertNull("Should have no metadata version", TestTables.metadataVersion("test_conflict"));
    Table conflict = TestTables.create(tableDir, "test_conflict", SCHEMA, unpartitioned(), formatVersion);
    Assert.assertEquals("Table schema should match with reassigned IDs", TypeUtil.assignIncreasingFreshIds(SCHEMA).asStruct(), conflict.schema().asStruct());
    Assert.assertEquals("Table spec should match conflict table, not transaction table", unpartitioned(), conflict.spec());
    Assert.assertFalse("Table should not have any snapshots", conflict.snapshots().iterator().hasNext());
    AssertHelpers.assertThrows("Transaction commit should fail", CommitFailedException.class, "Commit failed: table was updated", txn::commitTransaction);
    Assert.assertEquals("Should clean up metadata", Sets.newHashSet(), Sets.newHashSet(listManifestFiles(tableDir)));
}

