@Test
public void testTableScanHonorsIgnoreResiduals() throws IOException {
    table.newFastAppend().appendFile(FILE_A).appendFile(FILE_B).commit();
    TableScan scan1 = table.newScan().filter(Expressions.equal("id", 5));
    try (CloseableIterable<CombinedScanTask> tasks = scan1.planTasks()) {
        Assert.assertTrue("Tasks should not be empty", Iterables.size(tasks) > 0);
        for (CombinedScanTask combinedScanTask : tasks) {
            for (FileScanTask fileScanTask : combinedScanTask.files()) {
                Assert.assertNotEquals("Residuals must be preserved", Expressions.alwaysTrue(), fileScanTask.residual());
            }
        }
    }
    TableScan scan2 = table.newScan().filter(Expressions.equal("id", 5)).ignoreResiduals();
    try (CloseableIterable<CombinedScanTask> tasks = scan2.planTasks()) {
        Assert.assertTrue("Tasks should not be empty", Iterables.size(tasks) > 0);
        for (CombinedScanTask combinedScanTask : tasks) {
            for (FileScanTask fileScanTask : combinedScanTask.files()) {
                Assert.assertEquals("Residuals must be ignored", Expressions.alwaysTrue(), fileScanTask.residual());
            }
        }
    }
}

@Test
public void testUnpartitionedDeletes() {
    DeleteFileIndex index = new DeleteFileIndex(ImmutableMap.of(PartitionSpec.unpartitioned().specId(), PartitionSpec.unpartitioned(), 1, SPEC), new long[] { 3, 5, 5, 6 }, DELETE_FILES, ImmutableMap.of());
    Assert.assertArrayEquals("All deletes should apply to seq 0", DELETE_FILES, index.forDataFile(0, UNPARTITIONED_FILE));
    Assert.assertArrayEquals("All deletes should apply to seq 3", DELETE_FILES, index.forDataFile(3, UNPARTITIONED_FILE));
    Assert.assertArrayEquals("Last 3 deletes should apply to seq 4", Arrays.copyOfRange(DELETE_FILES, 1, 4), index.forDataFile(4, UNPARTITIONED_FILE));
    Assert.assertArrayEquals("Last 3 deletes should apply to seq 5", Arrays.copyOfRange(DELETE_FILES, 1, 4), index.forDataFile(5, UNPARTITIONED_FILE));
    Assert.assertArrayEquals("Last delete should apply to seq 6", Arrays.copyOfRange(DELETE_FILES, 3, 4), index.forDataFile(6, UNPARTITIONED_FILE));
    Assert.assertArrayEquals("No deletes should apply to seq 7", new DataFile[0], index.forDataFile(7, UNPARTITIONED_FILE));
    Assert.assertArrayEquals("No deletes should apply to seq 10", new DataFile[0], index.forDataFile(10, UNPARTITIONED_FILE));
    // copy file A with a different spec ID
    DataFile partitionedFileA = FILE_A.copy();
    ((BaseFile<?>) partitionedFileA).setSpecId(1);
    Assert.assertArrayEquals("All global deletes should apply to a partitioned file", DELETE_FILES, index.forDataFile(0, partitionedFileA));
}

@Test
public void testPartitionedDeleteIndex() {
    DeleteFileIndex index = new DeleteFileIndex(ImmutableMap.of(SPEC.specId(), SPEC, 1, PartitionSpec.unpartitioned()), null, null, ImmutableMap.of(Pair.of(SPEC.specId(), StructLikeWrapper.forType(SPEC.partitionType()).set(FILE_A.partition())), Pair.of(new long[] { 3, 5, 5, 6 }, DELETE_FILES), Pair.of(SPEC.specId(), StructLikeWrapper.forType(SPEC.partitionType()).set(FILE_C.partition())), Pair.of(new long[0], new DeleteFile[0])));
    Assert.assertArrayEquals("All deletes should apply to seq 0", DELETE_FILES, index.forDataFile(0, FILE_A));
    Assert.assertArrayEquals("All deletes should apply to seq 3", DELETE_FILES, index.forDataFile(3, FILE_A));
    Assert.assertArrayEquals("Last 3 deletes should apply to seq 4", Arrays.copyOfRange(DELETE_FILES, 1, 4), index.forDataFile(4, FILE_A));
    Assert.assertArrayEquals("Last 3 deletes should apply to seq 5", Arrays.copyOfRange(DELETE_FILES, 1, 4), index.forDataFile(5, FILE_A));
    Assert.assertArrayEquals("Last delete should apply to seq 6", Arrays.copyOfRange(DELETE_FILES, 3, 4), index.forDataFile(6, FILE_A));
    Assert.assertArrayEquals("No deletes should apply to seq 7", new DataFile[0], index.forDataFile(7, FILE_A));
    Assert.assertArrayEquals("No deletes should apply to seq 10", new DataFile[0], index.forDataFile(10, FILE_A));
