@Test
public void testUnpartitionedTableScan() throws IOException {
    File location = temp.newFolder();
    Assert.assertTrue(location.delete());
    Table unpartitioned = TestTables.create(location, "unpartitioned", SCHEMA, PartitionSpec.unpartitioned(), 2);
    unpartitioned.newAppend().appendFile(UNPARTITIONED_FILE).commit();
    // add a delete file
    unpartitioned.newRowDelta().addDeletes(UNPARTITIONED_POS_DELETES).commit();
    List<FileScanTask> tasks = Lists.newArrayList(unpartitioned.newScan().planFiles().iterator());
    Assert.assertEquals("Should have one task", 1, tasks.size());
    FileScanTask task = tasks.get(0);
    Assert.assertEquals("Should have the correct data file path", UNPARTITIONED_FILE.path(), task.file().path());
    Assert.assertEquals("Should have one associated delete file", 1, task.deletes().size());
    Assert.assertEquals("Should have expected delete file", UNPARTITIONED_POS_DELETES.path(), task.deletes().get(0).path());
    // add a second delete file
    unpartitioned.newRowDelta().addDeletes(UNPARTITIONED_EQ_DELETES).commit();
    tasks = Lists.newArrayList(unpartitioned.newScan().planFiles().iterator());
    task = tasks.get(0);
    Assert.assertEquals("Should have the correct data file path", UNPARTITIONED_FILE.path(), task.file().path());
    Assert.assertEquals("Should have two associated delete files", 2, task.deletes().size());
    Assert.assertEquals("Should have expected delete files", Sets.newHashSet(UNPARTITIONED_POS_DELETES.path(), UNPARTITIONED_EQ_DELETES.path()), Sets.newHashSet(Iterables.transform(task.deletes(), ContentFile::path)));
}

