@Test
public void testChangedPartitionSpec() {
    table.newAppend().appendFile(FILE_A).appendFile(FILE_B).commit();
    Snapshot snap = table.currentSnapshot();
    long commitId = snap.snapshotId();
    validateSnapshot(null, snap, 1, FILE_A, FILE_B);
    TableMetadata base = readMetadata();
    Assert.assertEquals("Should create 1 manifest for initial write", 1, base.currentSnapshot().allManifests().size());
    ManifestFile initialManifest = base.currentSnapshot().allManifests().get(0);
    validateManifest(initialManifest, seqs(1, 1), ids(commitId, commitId), files(FILE_A, FILE_B), statuses(Status.ADDED, Status.ADDED));
    // build the new spec using the table's schema, which uses fresh IDs
    PartitionSpec newSpec = PartitionSpec.builderFor(base.schema()).bucket("data", 16).bucket("id", 4).build();
    // commit the new partition spec to the table manually
    table.ops().commit(base, base.updatePartitionSpec(newSpec));
    Snapshot snap2 = table.currentSnapshot();
    V2Assert.assertEquals("Snapshot sequence number should be 1", 1, snap2.sequenceNumber());
    V2Assert.assertEquals("Last sequence number should be 1", 1, readMetadata().lastSequenceNumber());
    V1Assert.assertEquals("Table should end with last-sequence-number 0", 0, readMetadata().lastSequenceNumber());
    DataFile newFileY = DataFiles.builder(newSpec).withPath("/path/to/data-y.parquet").withFileSizeInBytes(10).withPartitionPath("data_bucket=2/id_bucket=3").withRecordCount(1).build();
    table.newAppend().appendFile(newFileY).commit();
    Snapshot lastSnapshot = table.currentSnapshot();
    V2Assert.assertEquals("Snapshot sequence number should be 2", 2, lastSnapshot.sequenceNumber());
    V2Assert.assertEquals("Last sequence number should be 2", 2, readMetadata().lastSequenceNumber());
    V1Assert.assertEquals("Table should end with last-sequence-number 0", 0, readMetadata().lastSequenceNumber());
    Assert.assertEquals("Should use 2 manifest files", 2, lastSnapshot.allManifests().size());
    // new manifest comes first
    validateManifest(lastSnapshot.allManifests().get(0), seqs(2), ids(lastSnapshot.snapshotId()), files(newFileY), statuses(Status.ADDED));
    Assert.assertEquals("Second manifest should be the initial manifest with the old spec", initialManifest, lastSnapshot.allManifests().get(1));
}

