@Test
public void testTruncateBinaryMin() {
    ByteBuffer test1 = ByteBuffer.wrap(new byte[] { 1, 1, (byte) 0xFF, 2 });
    // Output of test1 when truncated to 2 bytes
    ByteBuffer test1_2_expected = ByteBuffer.wrap(new byte[] { 1, 1 });
    ByteBuffer test2 = ByteBuffer.wrap(new byte[] { (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, 2 });
    ByteBuffer test2_2 = ByteBuffer.wrap(new byte[] { (byte) 0xFF, (byte) 0xFF });
    Comparator<ByteBuffer> cmp = Literal.of(test1).comparator();
    Assert.assertTrue("Truncated lower bound should be lower than or equal to the actual lower bound", cmp.compare(truncateBinaryMin(Literal.of(test1), 2).value(), test1) <= 0);
    Assert.assertTrue("Output must have the first two bytes of the input", cmp.compare(truncateBinaryMin(Literal.of(test1), 2).value(), test1_2_expected) == 0);
    Assert.assertTrue("No truncation required as truncate length is greater than the input size", cmp.compare(truncateBinaryMin(Literal.of(test1), 5).value(), test1) == 0);
    Assert.assertTrue("Truncated lower bound should be lower than or equal to the actual lower bound", cmp.compare(truncateBinaryMin(Literal.of(test2), 2).value(), test2) <= 0);
    Assert.assertTrue("Output must have the first two bytes of the input. A lower bound exists " + "even though the first two bytes are the max value", cmp.compare(truncateBinaryMin(Literal.of(test2), 2).value(), test2_2) == 0);
}

@Test
public void testTruncateBinaryMax() {
    ByteBuffer test1 = ByteBuffer.wrap(new byte[] { 1, 1, 2 });
    ByteBuffer test2 = ByteBuffer.wrap(new byte[] { 1, 1, (byte) 0xFF, 2 });
    ByteBuffer test3 = ByteBuffer.wrap(new byte[] { (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, 2 });
    ByteBuffer test4 = ByteBuffer.wrap(new byte[] { 1, 1, 0 });
    ByteBuffer expectedOutput = ByteBuffer.wrap(new byte[] { 1, 2 });
    Comparator<ByteBuffer> cmp = Literal.of(test1).comparator();
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateBinaryMax(Literal.of(test1), 2).value(), test1) >= 0);
    Assert.assertTrue("Output must have two bytes and the second byte of the input must be incremented", cmp.compare(truncateBinaryMax(Literal.of(test1), 2).value(), expectedOutput) == 0);
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateBinaryMax(Literal.of(test2), 2).value(), test2) >= 0);
    Assert.assertTrue("Since the third byte is already the max value, output must have two bytes " + "with the second byte incremented ", cmp.compare(truncateBinaryMax(Literal.of(test2), 3).value(), expectedOutput) == 0);
    Assert.assertTrue("No truncation required as truncate length is greater than the input size", cmp.compare(truncateBinaryMax(Literal.of(test3), 5).value(), test3) == 0);
    Assert.assertNull("An upper bound doesn't exist since the first two bytes are the max value", truncateBinaryMax(Literal.of(test3), 2));
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateBinaryMax(Literal.of(test4), 2).value(), test4) >= 0);
    Assert.assertTrue("Since a shorter sequence is considered smaller, output must have two bytes " + "and the second byte of the input must be incremented", cmp.compare(truncateBinaryMax(Literal.of(test4), 2).value(), expectedOutput) == 0);
}

