@SuppressWarnings("checkstyle:AvoidEscapedUnicodeCharacters")
@Test
public void testTruncateStringMax() {
    String test1 = "イロハニホヘト";
    // Output of test1 when truncated to 2 unicode characters
    String test1_2_expected = "イヮ";
    String test1_3_expected = "イロバ";
    String test2 = "щщаεはчωいにπάほхεろへσκζ";
    String test2_7_expected = "щщаεはчϊ";
    String test3 = "aनि\uFFFF\uFFFF";
    String test3_3_expected = "aनी";
    // U+FFFF is max 3 byte UTF-8 character
    String test4 = "\uFFFF\uFFFF";
    String test4_1_expected = "\uD800\uDC00";
    // test5 consists of 2 4 byte max UTF-8 characters
    String test5 = "\uDBFF\uDFFF\uDBFF\uDFFF";
    String test6 = "\uD800\uDFFF\uD800\uDFFF";
    // Increment the previous character
    String test6_2_expected = "\uD801\uDC00";
    String test7 = "\uD83D\uDE02\uD83D\uDE02\uD83D\uDE02";
    String test7_2_expected = "\uD83D\uDE02\uD83D\uDE03";
    String test7_1_expected = "\uD83D\uDE03";
    Comparator<CharSequence> cmp = Literal.of(test1).comparator();
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateStringMax(Literal.of(test1), 4).value(), test1) >= 0);
    Assert.assertTrue("No truncation required as truncate length is equal to the input size", cmp.compare(truncateStringMax(Literal.of(test1), 7).value(), test1) == 0);
    Assert.assertTrue("Output must have two characters and the second character of the input must " + "be incremented", cmp.compare(truncateStringMax(Literal.of(test1), 2).value(), test1_2_expected) == 0);
    Assert.assertTrue("Output must have three characters and the third character of the input must " + "be incremented", cmp.compare(truncateStringMax(Literal.of(test1), 3).value(), test1_3_expected) == 0);
    Assert.assertTrue("No truncation required as truncate length is greater than the input size", cmp.compare(truncateStringMax(Literal.of(test1), 8).value(), test1) == 0);
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper " + "bound", cmp.compare(truncateStringMax(Literal.of(test2), 8).value(), test2) >= 0);
    Assert.assertTrue("Output must have seven characters and the seventh character of the input " + "must be incremented", cmp.compare(truncateStringMax(Literal.of(test2), 7).value(), test2_7_expected) == 0);
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper " + "bound", cmp.compare(truncateStringMax(Literal.of(test3), 3).value(), test3) >= 0);
    Assert.assertTrue("Output must have three characters and the third character of the input must " + "be incremented. The second perceivable character in this string is actually a glyph. It consists of " + "two unicode characters", cmp.compare(truncateStringMax(Literal.of(test3), 3).value(), test3_3_expected) == 0);
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateStringMax(Literal.of(test4), 1).value(), test4) >= 0);
    Assert.assertTrue("Output must have one character. Since the first character is the max 3 byte " + "UTF-8 character, it should be incremented to the lowest 4 byte UTF-8 character", cmp.compare(truncateStringMax(Literal.of(test4), 1).value(), test4_1_expected) == 0);
    Assert.assertNull("An upper bound doesn't exist since the first two characters are max UTF-8 " + "characters", truncateStringMax(Literal.of(test5), 1));
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateStringMax(Literal.of(test6), 2).value(), test6) >= 0);
    Assert.assertTrue("Test 4 byte UTF-8 character increment. Output must have one character with " + "the first character incremented", cmp.compare(truncateStringMax(Literal.of(test6), 1).value(), test6_2_expected) == 0);
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateStringMax(Literal.of(test7), 2).value(), test7) >= 0);
    Assert.assertTrue("Test input with multiple 4 byte UTF-8 character where the second unicode " + "character should be incremented", cmp.compare(truncateStringMax(Literal.of(test7), 2).value(), test7_2_expected) == 0);
    Assert.assertTrue("Test input with multiple 4 byte UTF-8 character where the first unicode " + "character should be incremented", cmp.compare(truncateStringMax(Literal.of(test7), 1).value(), test7_1_expected) == 0);
}

