@Test
public void testSplits() {
    // case when the last row group has more than one byte
    verify(asList(4L, 10L, 15L, 18L, 30L, 45L), 48L, 20, asList(asList(4L, 14L), asList(18L, 12L), asList(30L, 18L)));
    // case when the last row group has 1 byte
    verify(asList(4L, 10L, 15L, 18L, 30L, 45L), 46L, 20, asList(asList(4L, 14L), asList(18L, 12L), asList(30L, 16L)));
    // case when every row group is of target split size
    verify(asList(4L, 24L, 44L, 64L, 84L, 104L), 124L, 20, asList(asList(4L, 20L), asList(24L, 20L), asList(44L, 20L), asList(64L, 20L), asList(84L, 20L), asList(104L, 20L)));
    // case when every row group except last one is of target split size
    verify(asList(4L, 24L, 44L, 64L, 84L, 104L), 108L, 20, asList(asList(4L, 20L), asList(24L, 20L), asList(44L, 20L), asList(64L, 20L), asList(84L, 20L), asList(104L, 4L)));
    // case when target split size is smaller than splits determined by offset boundaries
    verify(asList(4L, 24L, 44L, 64L, 84L, 104L), 108L, 2, asList(asList(4L, 20L), asList(24L, 20L), asList(44L, 20L), asList(64L, 20L), asList(84L, 20L), asList(104L, 4L)));
}

