@Test
public void testExpireOlderThan() {
    table.newAppend().appendFile(FILE_A).commit();
    Snapshot firstSnapshot = table.currentSnapshot();
    waitUntilAfter(table.currentSnapshot().timestampMillis());
    table.newAppend().appendFile(FILE_B).commit();
    long snapshotId = table.currentSnapshot().snapshotId();
    long tAfterCommits = waitUntilAfter(table.currentSnapshot().timestampMillis());
    Set<String> deletedFiles = Sets.newHashSet();
    table.expireSnapshots().expireOlderThan(tAfterCommits).deleteWith(deletedFiles::add).commit();
    Assert.assertEquals("Expire should not change current snapshot", snapshotId, table.currentSnapshot().snapshotId());
    Assert.assertNull("Expire should remove the oldest snapshot", table.snapshot(firstSnapshot.snapshotId()));
    Assert.assertEquals("Should remove only the expired manifest list location", Sets.newHashSet(firstSnapshot.manifestListLocation()), deletedFiles);
}

@Test
public void testExpireOlderThanWithDelete() {
    table.newAppend().appendFile(FILE_A).commit();
    Snapshot firstSnapshot = table.currentSnapshot();
    Assert.assertEquals("Should create one manifest", 1, firstSnapshot.allManifests().size());
    waitUntilAfter(table.currentSnapshot().timestampMillis());
    table.newDelete().deleteFile(FILE_A).commit();
    Snapshot secondSnapshot = table.currentSnapshot();
    Assert.assertEquals("Should create replace manifest with a rewritten manifest", 1, secondSnapshot.allManifests().size());
    table.newAppend().appendFile(FILE_B).commit();
    waitUntilAfter(table.currentSnapshot().timestampMillis());
    long snapshotId = table.currentSnapshot().snapshotId();
    long tAfterCommits = waitUntilAfter(table.currentSnapshot().timestampMillis());
    Set<String> deletedFiles = Sets.newHashSet();
    table.expireSnapshots().expireOlderThan(tAfterCommits).deleteWith(deletedFiles::add).commit();
    Assert.assertEquals("Expire should not change current snapshot", snapshotId, table.currentSnapshot().snapshotId());
    Assert.assertNull("Expire should remove the oldest snapshot", table.snapshot(firstSnapshot.snapshotId()));
    Assert.assertNull("Expire should remove the second oldest snapshot", table.snapshot(secondSnapshot.snapshotId()));
    Assert.assertEquals("Should remove expired manifest lists and deleted data file", Sets.newHashSet(// snapshot expired
    firstSnapshot.manifestListLocation(), // manifest was rewritten for delete
    firstSnapshot.allManifests().get(0).path(), // snapshot expired
    secondSnapshot.manifestListLocation(), // manifest contained only deletes, was dropped
    secondSnapshot.allManifests().get(0).path(), // deleted
    FILE_A.path()), deletedFiles);
}

