@Test
public void testFilterWithDateAndTimestamp() throws IOException {
    // TODO: Add multiple timestamp tests - there's an issue with ORC caching TZ in ThreadLocal, so it's not possible
    //   to change TZ and test with ORC as they will produce incompatible values.
    Schema schema = new Schema(required(1, "timestamp_with_zone", Types.TimestampType.withZone()), required(2, "timestamp_without_zone", Types.TimestampType.withoutZone()), required(3, "date", Types.DateType.get()), required(4, "time", Types.TimeType.get()));
    File tableLocation = temp.newFolder("complex_filter_table");
    Assert.assertTrue(tableLocation.delete());
    Table table = TABLES.create(schema, PartitionSpec.unpartitioned(), ImmutableMap.of(TableProperties.DEFAULT_FILE_FORMAT, format.name()), tableLocation.getAbsolutePath());
    List<Record> expected = RandomGenericData.generate(schema, 100, 435691832918L);
    DataFile file = writeFile(tableLocation.toString(), format.addExtension("record-file"), schema, expected);
    table.newFastAppend().appendFile(file).commit();
    for (Record r : expected) {
        Iterable<Record> filterResult = IcebergGenerics.read(table).where(equal("timestamp_with_zone", r.getField("timestamp_with_zone").toString())).where(equal("timestamp_without_zone", r.getField("timestamp_without_zone").toString())).where(equal("date", r.getField("date").toString())).where(equal("time", r.getField("time").toString())).build();
        Assert.assertTrue(filterResult.iterator().hasNext());
        Record readRecord = filterResult.iterator().next();
        Assert.assertEquals(r.getField("timestamp_with_zone"), readRecord.getField("timestamp_with_zone"));
    }
}

