    // Schema: [data, nested[f1, f2, f3], id]
    // Projection: [nested.f2, data]
    // The Flink SQL output: [f2, data]
    // The FlinkInputFormat output: [nested[f2], data]
    TableSchema projectedSchema = TableSchema.builder().field("nested", DataTypes.ROW(DataTypes.FIELD("f2", DataTypes.STRING()))).field("data", DataTypes.STRING()).build();
