    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("id", INT_MIN_VALUE - 2, INT_MIN_VALUE - 1)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: id below lower bound (28 < 30, 29 < 30). The two sets are disjoint.", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("id", INT_MIN_VALUE - 1, INT_MIN_VALUE)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: id equal to lower bound (30 == 30)", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("id", INT_MAX_VALUE - 4, INT_MAX_VALUE - 3)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: the notIn set is a subset of the dictionary", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("id", INT_MAX_VALUE, INT_MAX_VALUE + 1)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: id equal to upper bound (79 == 79)", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("id", INT_MAX_VALUE + 1, INT_MAX_VALUE + 2)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: id above upper bound (80 > 79, 81 > 79). The two sets are disjoint.", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("id", INT_MAX_VALUE + 6, INT_MAX_VALUE + 7)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: id above upper bound (85 > 79, 86 > 79). The two sets are disjoint.", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("id", IntStream.range(INT_MIN_VALUE - 10, INT_MAX_VALUE + 10).boxed().collect(Collectors.toList()))).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertFalse("Should not read: the dictionary is a subset of the notIn set", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("id", IntStream.range(INT_MIN_VALUE, INT_MAX_VALUE + 1).boxed().collect(Collectors.toList()))).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertFalse("Should not read: the dictionary is equal to the notIn set", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("all_nulls", 1, 2)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: notIn on all nulls column", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("some_nulls", "aaa", "bbb")).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: notIn on some nulls column (any null matches the notIn)", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("no_nulls", "aaa", "bbb")).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: notIn on no nulls column (empty string is not within the set)", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, notIn("no_nulls", "aaa", "")).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertFalse("Should not read: notIn on no nulls column (empty string is within the set)", shouldRead);
}

