    // this is our iceberg dataset to which we will append data
    new HadoopTables(newSparkSession.sessionState().newHadoopConf()).create(icebergSchema, PartitionSpec.builderFor(icebergSchema).identity("requiredField").build(), tableProperties, targetPath);
    // this is the initial data inside the iceberg dataset
    newSparkSession.read().schema(sparkSchema).json(JavaSparkContext.fromSparkContext(spark.sparkContext()).parallelize(data0)).write().format("iceberg").mode(SaveMode.Append).save(targetPath);
    // read from parquet and append to iceberg
    newSparkSession.read().schema(SparkSchemaUtil.convert(icebergSchema)).parquet(sourcePath).write().format("iceberg").mode(SaveMode.Append).save(targetPath);
