    List<SimpleRecord> previousSnapshotRecords = previousSnapshotResult.orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    Assert.assertEquals("Previous snapshot rows should match", firstBatchRecords, previousSnapshotRecords);
