    File parent = temp.newFolder(format.toString());
    File location = new File(parent, "test");
    HadoopTables tables = new HadoopTables(CONF);
    PartitionSpec spec = PartitionSpec.builderFor(SCHEMA).identity("data").build();
    tables.create(SCHEMA, spec, location.toString());
    List<SimpleRecord> records = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "c"));
    Dataset<Row> df = spark.createDataFrame(records, SimpleRecord.class);
    df.select("id", "data").write().format("iceberg").option("write-format", format.toString()).mode("append").save(location.toString());
    Dataset<Row> query = spark.read().format("iceberg").load(location.toString()).where("id = 1");
    query.createOrReplaceTempView("tmp");
    List<SimpleRecord> actual1 = spark.table("tmp").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    List<SimpleRecord> expected1 = Lists.newArrayList(new SimpleRecord(1, "a"));
    Assert.assertEquals("Number of rows should match", expected1.size(), actual1.size());
    Assert.assertEquals("Result rows should match", expected1, actual1);
    df.select("id", "data").write().format("iceberg").option("write-format", format.toString()).mode("append").save(location.toString());
    List<SimpleRecord> actual2 = spark.table("tmp").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    List<SimpleRecord> expected2 = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(1, "a"));
    Assert.assertEquals("Number of rows should match", expected2.size(), actual2.size());
    Assert.assertEquals("Result rows should match", expected2, actual2);
}

@Test
public void testEqualityDeleteWithFilter() throws IOException {
    String tableName = "test_with_filter";
    Table table = createTable(tableName, SCHEMA, SPEC);
    Schema deleteRowSchema = table.schema().select("data");
    Record dataDelete = GenericRecord.create(deleteRowSchema);
    List<Record> dataDeletes = Lists.newArrayList(// id = 29
    dataDelete.copy("data", "a"), // id = 89
    dataDelete.copy("data", "d"), // id = 122
    dataDelete.copy("data", "g"));
    DeleteFile eqDeletes = FileHelpers.writeDeleteFile(table, Files.localOutput(temp.newFile()), TestHelpers.Row.of(0), dataDeletes, deleteRowSchema);
    table.newRowDelta().addDeletes(eqDeletes).commit();
    Types.StructType projection = table.schema().select("*").asStruct();
    Dataset<Row> df = spark.read().format("iceberg").load(TableIdentifier.of("default", tableName).toString()).filter(// select a deleted row
    "data = 'a'").selectExpr("*");
    StructLikeSet actual = StructLikeSet.create(projection);
    df.collectAsList().forEach(row -> {
        SparkStructLike rowWrapper = new SparkStructLike(projection);
        actual.add(rowWrapper.wrap(row));
    });
    Assert.assertEquals("Table should contain no rows", 0, actual.size());
}

