    spark.conf().set("spark.sql.shuffle.partitions", "1");
    try {
        sql("CREATE TABLE %s (id bigint NOT NULL, data string) USING iceberg", tableName);
        sql("INSERT INTO TABLE %s VALUES (1, 'a'), (2, 'b'), (3, 'c')", tableName);
        assertEquals("Should have expected rows", ImmutableList.of(row(1L, "a"), row(2L, "b"), row(3L, "c")), sql("SELECT * FROM %s ORDER BY id", tableName));
        AssertHelpers.assertThrows("Should not delete when not all rows of a file match the filter", IllegalArgumentException.class, "Failed to cleanly delete data files", () -> sql("DELETE FROM %s WHERE id < 2", tableName));
        sql("DELETE FROM %s WHERE id < 4", tableName);
        Assert.assertEquals("Should have no rows after successful delete", 0L, scalarSql("SELECT count(1) FROM %s", tableName));
    } finally {
        spark.conf().set("spark.sql.shuffle.partitions", originalParallelism);
    }
}

@Test
public void testDeleteFromPartitionedTable() {
    // set the shuffle partitions to 1 to force the write to use a single task and produce 1 file per partition
    String originalParallelism = spark.conf().get("spark.sql.shuffle.partitions");
    spark.conf().set("spark.sql.shuffle.partitions", "1");
    try {
        sql("CREATE TABLE %s (id bigint NOT NULL, data string) USING iceberg " + "PARTITIONED BY (truncate(id, 2))", tableName);
        sql("INSERT INTO TABLE %s VALUES (1, 'a'), (2, 'b'), (3, 'c')", tableName);
        assertEquals("Should have 3 rows in 2 partitions", ImmutableList.of(row(1L, "a"), row(2L, "b"), row(3L, "c")), sql("SELECT * FROM %s ORDER BY id", tableName));
        AssertHelpers.assertThrows("Should not delete when not all rows of a file match the filter", IllegalArgumentException.class, "Failed to cleanly delete data files", () -> sql("DELETE FROM %s WHERE id > 2", tableName));
        sql("DELETE FROM %s WHERE id < 2", tableName);
        assertEquals("Should have two rows in the second partition", ImmutableList.of(row(2L, "b"), row(3L, "c")), sql("SELECT * FROM %s ORDER BY id", tableName));
    } finally {
        spark.conf().set("spark.sql.shuffle.partitions", originalParallelism);
    }
}

